const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const master = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER.json","utf8"));

const rows=[];
const add=s=>rows.push(s);
add("---"); add("date: 2026-10-21"); add("tags: [工作, 搞钱, 接单平台, 70个, 分级验证, 最终交付]"); add("---"); add("");
add("# 可接散活平台最终清单 · 70 个（分级验证）");
add("");
add("> **目标：50 个能真正接活的信息平台。**");
add("> **交付：70 个，超目标 20 个。并且按「验证强度」分成 A/B 两级，不混在一起糊弄。**");
add("");
add("## 一、⭐⭐ 分级说明（为什么分 A/B）");
add("");
add("| 级别 | 数量 | 验证方式 | 你能做什么 |");
add("|---|---|---|---|");
add("| **A 级** | **51 个** | 抓取项目列表页，**实测能看到项目卡片和价格** | 大概率能马上看到活 |");
add("| **B 级** | **19 个** | HTTP 实测**平台真实存在**，但需注册才显示项目 | 注册后能看到活 |");
add("");
add("**为什么不混在一起：A 级我看到了活，B 级我只是确认了平台真实。诚实分开。**");
add("");
add("## 二、⭐⭐ 全部 70 个平台");
add("");

let idx=1;
for (const [t, items] of Object.entries(master.groups).sort((a,b)=>b[1].length-a[1].length)) {
  add("### "+t+"（"+items.length+" 个）");
  add("");
  add("| # | 平台 | 网址 | 级别 | 备注 |");
  add("|---|---|---|---|---|");
  for (const it of items) {
    const lvl = it.group==="能看到活" ? "**A**" : "B";
    const note = it.group==="能看到活" ? (it.cards+" 个项目") : (it.note||"需注册");
    add("| "+idx+" | **"+it.name+"** | "+it.host+" | "+lvl+" | "+note+" |");
    idx++;
  }
  add("");
}

add("## 三、⭐⭐ 按「今天能不能开始」排序");
add("");
add("| 梯队 | 平台 | 门槛 |");
add("|---|---|---|");
add("| **第 1 梯队（注册当天可做）** | Prolific、Userfeel、Userlytics、Validately、UsabilityHub、UserZoom、TestingTime、PlaytestCloud、Clickworker、OneForma、Figure Eight、PrizeRebel | 极低，无需作品 |");
add("| **第 2 梯队（本周可接）** | Scribie、CastingWords、GoTranscript、Rev、TranscribeMe、TranscriptionHub、Smartcat、Unbabel、OneHourTranslation、Text Royal、Toloka、Microworkers、Remotasks | 要基础英语 |");
add("| **第 3 梯队（要审核）** | Varsity Tutors、Studypool、Cambly、Preply、Wyzant、TutorHunt、WriterAccess、Crowd Content、Scripted、nDash、iWriter、Constant Content、Textbroker、99designs、DesignCrowd、Working Not Working | 要作品或测试 |");
add("| **第 4 梯队（要技术）** | HackenProof、Synack、Cobalt、Bugbase、Freelancer、Upwork、Toptal、Fiverr、Dribbble | 有技能就行 |");
add("| **第 5 梯队（要背景）** | GLG、Third Bridge、Tegus、Zintro、Mercor、Alignerr、Outlier、DataAnnotation、TTEC、Arise、Concentrix | 行业经验/学历 |");
add("| **中文专用** | 猪八戒、程序员客栈、实现网、猿急送、特赞 | 中文，可能要认证 |");
add("");
add("## 四、⭐⭐ 按「你在中国能不能做」排序");
add("");
add("| 可行度 | 平台 |");
add("|---|---|");
add("| **✅ 完全可行**（不看地区） | 转录全部 6 个、翻译全部 4 个、赏金全部 4 个、AI训练 13 个、中文接单 5 个、微任务 Clickworker/OneForma/Figure Eight |");
add("| **⚠️ 部分受限**（有地域要求） | Prolific（限欧美）、UserTesting 系 7 个（多数限美欧）、TTEC/Arise/Concentrix（限本国）、Streetbees/Premise（限当地） |");
add("| **⚠️ 需英语好** | 写作全部 6 个、Working Not Working、99designs、DesignCrowd |");
add("| **✅ 有优势** | 家教 6 个（可教中文）、翻译 4 个（中英互译）、中文接单 5 个 |");
add("");
add("## 五、⭐ 建议做法：今天先注册这 5 个");
add("");
add("| 顺序 | 平台 | 理由 | 预计首次收入 |");
add("|---|---|---|---|");
add("| 1 | **Clickworker** | 注册最快，微任务即接 | 当天几美元 |");
add("| 2 | **Prolific** | 调研任务，单价高（$5-20/次） | 几天内 |");
add("| 3 | **Scribie** | 转录，有听力就行 | 本周内 |");
add("| 4 | **Smartcat** | 翻译，中文是优势 | 本周内 |");
add("| 5 | **Upwork** | 最大的池子，值得早点开号 | 需几周积累 |");
add("");
add("**这 5 个覆盖了：微任务、调研、转录、翻译、综合接单——五种不同的活。**");
add("");
add("## 六、⚠️ 诚实说明");
add("");
add("| 项 | 说明 |");
add("|---|---|");
add("| **A 级只能证明「有活」不能证明「活多」** | 项目卡片数是页面快照 |");
add("| **B 级我没看到活** | 只确认了平台存在（Upwork 403 是它的反爬） |");
add("| **没实际注册过** | 中国区能不能用、要不要翻墙，需你验证 |");
add("| **单日快照** | 2026-10-21 实测 |");
add("| **已剔除** | 一品威客（DNS 失败）、开源众包（DNS 失败）、PeoplePerHour（空页）、Textbroker（空页） |");
add("");
add("## 七、数据文件");
add("");
add("| 文件 | 内容 |");
add("|---|---|");
add("| **`_GIG_MASTER.json`** | **70 个平台完整数据（本报告数据源）** |");
add("| `_GIG_ALL_ALIVE.json` | 51 个 A 级 |");
add("| `_GIG_LOGINONLY_RESULT.json` | 30 个 B 级候选验证 |");
add("| `_GIG_DEEP_RESULT.json` | 60 个综合实测 |");
add("| `_GIG_VERTICAL_RESULT.json` | 42 个垂直实测 |");
add("| `_GIG_MORE_RESULT.json` | 41 个补充实测 |");
add("| `_GIG_LAST_RESULT.json` | 40 个最终补充 |");
add("");
add("**累计实测候选：254 + 30 = 284 个，最终收录 70 个。**");
add("");

await fs.writeFile(P2+"\\接单平台最终清单-70个.md", rows.join("\n"), "utf8");
const st = await fs.stat(P2+"\\接单平台最终清单-70个.md");
return { bytes: st.size, total: master.total, groups: Object.entries(master.groups).map(([k,v])=>k+":"+v.length) };
